import assert from 'node:assert/strict';import {readFile,writeFile} from 'node:fs/promises';import path from 'node:path';import {chromium} from 'playwright';
const root=path.resolve(process.argv[2]||'work/uae'),records=JSON.parse(await readFile(path.join(root,'ultimate-records.json'),'utf8')),browser=await chromium.launch({channel:'chrome'}),results=[];
try{for(const record of records)for(const width of [1440,390]){const page=await browser.newPage({viewport:{width,height:900}});page.setDefaultTimeout(12000);await page.goto(record.url,{waitUntil:'networkidle'});const widget=page.locator('.elementor-widget-navigation-menu');assert.equal(await widget.count(),1);await widget.scrollIntoViewIfNeeded();const toggle=widget.locator('.hfe-nav-menu__toggle'),nav=widget.locator('nav'),button=widget.locator('.hfe-has-submenu-container').first(),submenu=widget.locator('.sub-menu').first();
 await widget.screenshot({path:path.join(root,'menu-'+record.layout+'-'+width+'-closed.png')});const toggleVisible=await toggle.isVisible();if(toggleVisible)await toggle.click();if(record.layout==='horizontal'&&width===1440)await button.hover();else await button.click();await page.waitForFunction(()=>{const panel=document.querySelector('.elementor-widget-navigation-menu .sub-menu'),s=getComputedStyle(panel);return s.visibility==='visible'&&Number(s.opacity)>0&&panel.getBoundingClientRect().height>0;});const a=await widget.boundingBox(),b=await submenu.boundingBox(),x=Math.floor(Math.min(a.x,b.x)),y=Math.floor(Math.min(a.y,b.y));await page.screenshot({path:path.join(root,'menu-'+record.layout+'-'+width+'-open.png'),clip:{x,y,width:Math.ceil(Math.max(a.x+a.width,b.x+b.width)-x),height:Math.ceil(Math.max(a.y+a.height,b.y+b.height)-y)}});await writeFile(path.join(root,'menu-'+record.layout+'-'+width+'.html'),await widget.evaluate(el=>el.outerHTML));results.push({layout:record.layout,width,toggleVisible,submenuOpen:true,navClass:await nav.getAttribute('class')});await page.close();}await writeFile(path.join(root,'ultimate-source-check.json'),JSON.stringify(results,null,2));console.log(JSON.stringify(results));}finally{await browser.close();}
